float disk_graph(vec2 p, float seed) {
    float r=length(p),T=6.283;
    vec2 x=vec2(floor(r),ceil(r)),
    U=round(x*T),
    a=atan(p.y,p.x)/T*U+37.*sin((16.+x)*seed);
    if(x.x==.0)a.x=a.y*.5;
    a=fract(a);
    return abs(1.-2.*abs(mix(a.x,a.y+round(a.x-a.y),r-x.x)-.5));
}

void mainImage(out vec4 O,vec2 C){
    vec2 uv=(C-iResolution.xy*0.5)/12.;
    float d=disk_graph(uv,iTime*5e-4+3.); 
    O=log(vec4(.3,.6,.9,0)*d+0.75)*4./(1.+0.045*length(uv));
}
